import pytest
from candidate import triangle_area

class TestTriangleAreaNormalCases:
    def test_triangle_area_positive_integers(self):
        self = None
        assert triangle_area(5, 3) == 7.5

    def test_triangle_area_positive_floats(self):
        assert triangle_area(4.5, 2.5) == 5.625

    def test_triangle_area_integer_and_float(self):
        assert triangle_area(10, 3.5) == 17.5

    def test_triangle_area_doctest_example(self):
        assert triangle_area(5, 3) == 7.5

    def test_triangle_area_unit_side_and_height(self):
        assert triangle_area(1, 1) == 0.5

    def test_triangle_area_large_numbers(self):
        assert triangle_area(1000000, 2000000) == 1000000000000.0

    def test_triangle_area_very_small_numbers(self):
        assert triangle_area(0.001, 0.002) == 0.000001

    def test_triangle_area_returns_float_type(self):
        result = triangle_area(4, 4)
        assert isinstance(result, float)

    def test_triangle_area_integer_inputs_return_float(self):
        result = triangle_area(2, 3)
        assert isinstance(result, float)

class TestTriangleAreaBoundaryConditions:
    def test_triangle_area_zero_side(self):
        assert triangle_area(0, 5) == 0.0

    def test_triangle_area_zero_height(self):
        assert triangle_area(5, 0) == 0.0

    def test_triangle_area_both_zero(self):
        assert triangle_area(0, 0) == 0.0

    def test_triangle_area_negative_side(self):
        assert triangle_area(-5, 3) == -7.5

    def test_triangle_area_negative_height(self):
        assert triangle_area(5, -3) == -7.5

    def test_triangle_area_both_negative(self):
        assert triangle_area(-5, -3) == 7.5

    def test_triangle_area_mixed_negative(self):
        assert triangle_area(-4, 6) == -12.0

class TestTriangleAreaErrorConditions:
    def test_triangle_area_none_side_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(None, 3)

    def test_triangle_area_none_height_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(5, None)

    def test_triangle_area_both_none_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(None, None)

    def test_triangle_area_string_side_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area("5", 3)

    def test_triangle_area_string_height_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(5, "3")

    def test_triangle_area_list_side_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area([5], 3)

    def test_triangle_area_dict_height_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(5, {"h": 3})

    def test_triangle_area_no_arguments_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area()

    def test_triangle_area_one_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(5)

    def test_triangle_area_too_many_arguments_raises_type_error(self):
        with pytest.raises(TypeError):
            triangle_area(5, 3, 1)

class TestTriangleAreaEdgeCases:
    def test_triangle_area_float_precision(self):
        assert triangle_area(1, 3) == 1.5

    def test_triangle_area_float_multiplication(self):
        assert triangle_area(0.1, 0.2) == 0.01

    def test_triangle_area_one_as_side(self):
        assert triangle_area(1, 100) == 50.0

    def test_triangle_area_one_as_height(self):
        assert triangle_area(100, 1) == 50.0

    def test_triangle_area_unity_values(self):
        assert triangle_area(2, 1) == 1.0

    def test_triangle_area_symmetric_values(self):
        assert triangle_area(7, 7) == 24.5

    def test_triangle_area_commutative(self):
        assert triangle_area(3, 10) == triangle_area(10, 3)
